return [
  {
    json: {
      googleMapsInput: "Gyms in 75002, Allen, Texas",
      targetService: "Digital marketing and SEO services",
      maxPages: 3
    }
  }
];

const state = $getWorkflowStaticData('global');
const runId = $execution.id;

if (state.runId !== runId) {
  state.runId = runId;
  state.allListings = [];
  state.pageCount = 0;
}

const response = $json;

const listings = Array.isArray(response.listing_data)
  ? response.listing_data
  : [];

state.allListings.push(...listings);
state.pageCount += 1;

const nextPageUrl =
  typeof response.next_page_url === 'string' &&
  response.next_page_url.trim()
    ? response.next_page_url.trim()
    : null;

const maxPagesRaw = $('Set Google Maps Search Parameters').first().json.maxPages;
const maxPages = Math.max(1, Number(maxPagesRaw) || 3);

const reachedMaxPages = state.pageCount >= maxPages;
const hasNextPage = Boolean(nextPageUrl) && !reachedMaxPages;

return [
  {
    json: {
      page: state.pageCount,
      page_listing_count: listings.length,
      total_listing_count: state.allListings.length,
      has_next_page: hasNextPage,
      next_page_url: hasNextPage ? nextPageUrl : null,
      reached_max_pages: reachedMaxPages,
      max_pages: maxPages
    }
  }
];

const state = $getWorkflowStaticData('global');

return [
  {
    json: {
      total_pages: state.pageCount || 0,
      total_listings: state.allListings?.length || 0,
      listing_data: state.allListings || []
    }
  }
];

return $input.all().map(item => {
  const data = item.json;

  return {
    json: {
      business_name: data.name || data.business_name || '',
      category: data.category || data.type || '',
      address: data.address || '',
      phone: data.phone || data.phone_number || '',
      website: data.website || '',
      rating: data.rating ?? '',
      review_count: data.review_count ?? data.reviews ?? data.reviews_count ?? '',
      google_maps_url: data.google_maps_url || data.url || '',
      description: data.description || ''
    }
  };
});

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  const data = item.json;

  const name = String(data.business_name || '').trim().toLowerCase();
  const address = String(data.address || '').trim().toLowerCase();
  const phone = String(data.phone || '').trim().toLowerCase();
  const mapsUrl = String(data.google_maps_url || '').trim().toLowerCase();

  const key = mapsUrl || `${name}|${address}|${phone}`;

  if (!key || seen.has(key)) continue;

  seen.add(key);
  output.push(item);
}

return output;

const rawOutput = $json.output;

let aiData = rawOutput;

if (typeof rawOutput === 'string') {
  const cleaned = rawOutput
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    aiData = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(`Could not parse AI output as JSON: ${cleaned}`);
  }
}

if (!aiData || typeof aiData !== 'object') {
  throw new Error('AI output is not a valid structured object.');
}

return {
  json: {
    business_name: $json.business_name || '',
    category: $json.category || '',
    address: $json.address || '',
    phone: $json.phone || '',
    website: $json.website || '',
    rating: $json.rating || '',
    review_count: $json.review_count || '',
    google_maps_url: $json.google_maps_url || '',
    description: $json.description || '',
    business_type: aiData.business_type || '',
    lead_quality: aiData.lead_quality || '',
    lead_score: aiData.lead_score ?? '',
    target_fit: aiData.target_fit || '',
    has_website: aiData.has_website || '',
    has_phone: aiData.has_phone || '',
    rating_quality: aiData.rating_quality || '',
    key_signal: aiData.key_signal || '',
    reason: aiData.reason || '',
    recommended_action: aiData.recommended_action || ''
  }
};
